'use client'

import { useEffect, useState } from 'react'
import { AreaChart, BarChart3, Bell, BookOpen, Box, ChevronDown, ChevronRight, CircleHelp, Code2, Command, Copy, FileCode2, GitBranch, GitPullRequest, HelpCircle, LayoutDashboard, LineChart, LogOut, Menu, Moon, MoreHorizontal, Package, PanelLeft, Search, Settings as SettingsIcon, ShieldCheck, Sparkles, Sun, Users, X, Zap } from 'lucide-react'
import { cn } from '@/lib/utils'

type Tone = 'healthy' | 'warning' | 'critical' | 'neutral'

const nav = [
  { label: 'Dashboard', href: '/app/dashboard', icon: LayoutDashboard },
  { label: 'Repositories', href: '/app/repositories', icon: Box },
  { label: 'Pull Requests', href: '/app/pull-requests', icon: GitPullRequest, count: 12 },
  { label: 'Code Quality', href: '/app/code-quality', icon: Code2 },
  { label: 'Security', href: '/app/security', icon: ShieldCheck, count: 3 },
  { label: 'Dependencies', href: '/app/dependencies', icon: Package },
  { label: 'Analytics', href: '/app/analytics', icon: LineChart },
]
const bottomNav = [
  { label: 'Settings', href: '/app/settings', icon: SettingsIcon },
  { label: 'Help center', href: '/app/help', icon: CircleHelp },
]

const repositories = [
  { name: 'payment-service', owner: 'acme-platform', language: 'TypeScript', health: 86, risk: 'Low', prs: 4, security: 'A', coverage: '82%', updated: '12 min ago', tone: 'healthy' as Tone },
  { name: 'identity-platform', owner: 'acme-platform', language: 'Go', health: 74, risk: 'Medium', prs: 7, security: 'B', coverage: '76%', updated: '36 min ago', tone: 'warning' as Tone },
  { name: 'commerce-api', owner: 'acme-commerce', language: 'Python', health: 91, risk: 'Low', prs: 2, security: 'A', coverage: '89%', updated: '1 hr ago', tone: 'healthy' as Tone },
  { name: 'customer-portal', owner: 'acme-platform', language: 'TypeScript', health: 62, risk: 'High', prs: 9, security: 'C', coverage: '64%', updated: '3 hrs ago', tone: 'critical' as Tone },
]
const pullRequests = [
  { id: 142, title: 'Improve payment authorization', repo: 'payment-service', author: 'AM', risk: 72, files: 18, coverage: '58%', issues: 3, status: 'Needs review', age: '2h ago' },
  { id: 138, title: 'Add session rotation middleware', repo: 'identity-platform', author: 'JL', risk: 48, files: 9, coverage: '91%', issues: 0, status: 'Open', age: '5h ago' },
  { id: 97, title: 'Refactor checkout tax calculation', repo: 'commerce-api', author: 'SK', risk: 31, files: 6, coverage: '86%', issues: 1, status: 'Open', age: 'Yesterday' },
  { id: 89, title: 'Update account recovery flow', repo: 'customer-portal', author: 'RS', risk: 64, files: 22, coverage: '67%', issues: 4, status: 'Open', age: 'Yesterday' },
]

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5"><div className="relative grid size-8 place-items-center rounded-lg bg-primary text-primary-foreground shadow-sm"><span className="font-mono text-lg font-bold tracking-tighter">V</span><span className="absolute bottom-1.5 left-2.5 h-0.5 w-3 bg-cyan-300" /></div>{!compact && <span className="text-[15px] font-semibold tracking-[0.22em] text-foreground">VERION</span>}</div>
}

function StatusDot({ tone }: { tone: Tone }) { return <span aria-label={tone} className={cn('inline-block size-2 rounded-full', tone === 'healthy' && 'bg-emerald-500', tone === 'warning' && 'bg-amber-500', tone === 'critical' && 'bg-red-500', tone === 'neutral' && 'bg-muted-foreground')} /> }
function Score({ value, tone = 'healthy' }: { value: number; tone?: Tone }) { return <span className={cn('font-mono text-sm font-semibold', tone === 'healthy' && 'text-emerald-600 dark:text-emerald-400', tone === 'warning' && 'text-amber-600 dark:text-amber-400', tone === 'critical' && 'text-red-600 dark:text-red-400')}>{value}</span> }
function Badge({ children, tone = 'neutral' }: { children: React.ReactNode; tone?: Tone }) { return <span className={cn('inline-flex items-center gap-1.5 rounded-md border px-2 py-1 text-[11px] font-medium', tone === 'healthy' && 'border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900/60 dark:bg-emerald-950/40 dark:text-emerald-300', tone === 'warning' && 'border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/60 dark:bg-amber-950/40 dark:text-amber-300', tone === 'critical' && 'border-red-200 bg-red-50 text-red-700 dark:border-red-900/60 dark:bg-red-950/40 dark:text-red-300', tone === 'neutral' && 'border-border bg-muted/50 text-muted-foreground')}><StatusDot tone={tone} />{children}</span> }

function MiniChart({ color = 'primary', bars = false }: { color?: 'primary' | 'cyan' | 'green' | 'amber'; bars?: boolean }) {
  const stroke = color === 'cyan' ? '#06b6d4' : color === 'green' ? '#10b981' : color === 'amber' ? '#f59e0b' : '#6366f1'
  if (bars) return <div className="flex h-14 items-end gap-1.5">{[44, 62, 38, 70, 55, 82, 65, 90, 72, 78, 88, 94].map((height, i) => <span key={i} className="flex-1 rounded-t-sm bg-primary/15" style={{ height: `${height}%`, backgroundColor: i > 8 ? `${stroke}30` : undefined }} />)}</div>
  return <svg className="h-14 w-full overflow-visible" preserveAspectRatio="none" viewBox="0 0 300 56" role="img" aria-label="Trend chart"><path d="M0 44 C20 42 25 36 42 39 S68 29 82 32 S106 42 124 31 S149 25 165 29 S188 18 204 23 S224 20 240 17 S267 22 300 7" fill="none" stroke={stroke} strokeWidth="2.5" strokeLinecap="round" /><path d="M0 44 C20 42 25 36 42 39 S68 29 82 32 S106 42 124 31 S149 25 165 29 S188 18 204 23 S224 20 240 17 S267 22 300 7 L300 56 L0 56Z" fill={stroke} opacity=".08" /></svg>
}

function MetricCard({ label, value, detail, trend, tone = 'healthy', chart = 'line' }: { label: string; value: string; detail: string; trend: string; tone?: Tone; chart?: 'line' | 'bars' }) { return <div className="rounded-xl border border-border/80 bg-card p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-medium text-muted-foreground">{label}</p><div className="mt-2 flex items-baseline gap-2"><span className="font-mono text-2xl font-semibold tracking-tight">{value}</span><span className={cn('text-xs font-medium', tone === 'healthy' && 'text-emerald-600 dark:text-emerald-400', tone === 'warning' && 'text-amber-600 dark:text-amber-400', tone === 'critical' && 'text-red-600 dark:text-red-400')}>{trend}</span></div></div><button aria-label={`Learn about ${label}`} className="text-muted-foreground hover:text-foreground"><HelpCircle className="size-4" /></button></div><div className="mt-3"><MiniChart color={tone === 'critical' ? 'amber' : tone === 'warning' ? 'amber' : 'primary'} bars={chart === 'bars'} /></div><p className="mt-2 text-[11px] text-muted-foreground">{detail}</p></div> }

function Sidebar({ path, onNavigate, open, onClose }: { path: string; onNavigate: (href: string) => void; open: boolean; onClose: () => void }) { return <><div className={cn('fixed inset-0 z-40 bg-foreground/20 backdrop-blur-sm transition-opacity md:hidden', open ? 'opacity-100' : 'pointer-events-none opacity-0')} onClick={onClose} /><aside className={cn('fixed inset-y-0 left-0 z-50 flex w-64 flex-col border-r border-sidebar-border bg-sidebar px-3 py-4 transition-transform md:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center justify-between px-3 pb-7"><Logo /><button className="rounded-md p-1.5 text-sidebar-foreground/60 hover:bg-sidebar-accent md:hidden" onClick={onClose} aria-label="Close navigation"><X className="size-4" /></button></div><div className="mb-5 px-2"><button className="flex w-full items-center gap-2 rounded-lg border border-sidebar-border bg-sidebar-accent/50 px-3 py-2 text-left text-xs text-sidebar-foreground/70 hover:bg-sidebar-accent" onClick={() => onNavigate('/app/dashboard')}><div className="grid size-6 place-items-center rounded-md bg-primary text-[10px] font-semibold text-primary-foreground">AP</div><div className="min-w-0 flex-1"><p className="truncate font-medium text-sidebar-foreground">Acme Platform</p><p className="text-[10px] text-sidebar-foreground/55">Engineering</p></div><ChevronDown className="size-3.5" /></button></div><nav aria-label="Main navigation" className="flex flex-1 flex-col gap-1">{nav.map(item => { const Icon = item.icon; const active = path === item.href || (item.href !== '/app/dashboard' && path.startsWith(item.href)); return <button key={item.href} onClick={() => onNavigate(item.href)} className={cn('group flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors', active ? 'bg-sidebar-primary text-sidebar-primary-foreground shadow-sm' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground')}><Icon className="size-4" /><span className="flex-1 text-left">{item.label}</span>{item.count && <span className={cn('rounded-full px-1.5 py-0.5 text-[10px]', active ? 'bg-primary-foreground/15' : 'bg-sidebar-accent')}>{item.count}</span>}</button>})}<div className="mt-auto flex flex-col gap-1 border-t border-sidebar-border pt-4">{bottomNav.map(item => { const Icon = item.icon; return <button key={item.href} onClick={() => onNavigate(item.href)} className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground"><Icon className="size-4" /><span>{item.label}</span></button>})}</div></nav><div className="mt-4 rounded-lg border border-sidebar-border bg-sidebar-accent/30 p-3"><div className="flex items-center gap-2"><Sparkles className="size-4 text-cyan-500" /><span className="text-xs font-medium">AI review credits</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-sidebar-accent"><div className="h-full w-3/4 rounded-full bg-cyan-500" /></div><p className="mt-2 text-[10px] text-sidebar-foreground/55">750 of 1,000 reviews left</p></div></aside></> }

function Topbar({ onMenu, onCommand, onTheme }: { onMenu: () => void; onCommand: () => void; onTheme: () => void }) { return <header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-border/80 bg-background/90 px-4 backdrop-blur md:px-8"><div className="flex items-center gap-3"><button className="rounded-lg border border-border p-2 md:hidden" onClick={onMenu} aria-label="Open navigation"><Menu className="size-4" /></button><button onClick={onCommand} className="hidden h-9 w-64 items-center gap-2 rounded-lg border border-border bg-muted/35 px-3 text-left text-xs text-muted-foreground sm:flex"><Search className="size-3.5" /><span className="flex-1">Search anything</span><kbd className="rounded border border-border bg-background px-1.5 py-0.5 font-mono text-[10px]">⌘ K</kbd></button><button onClick={onCommand} className="rounded-lg border border-border p-2 text-muted-foreground sm:hidden" aria-label="Search"><Search className="size-4" /></button></div><div className="flex items-center gap-2"><button onClick={onTheme} aria-label="Toggle theme" className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground"><Sun className="size-4 dark:hidden" /><Moon className="hidden size-4 dark:block" /></button><button aria-label="Notifications" className="relative rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground"><Bell className="size-4" /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-red-500" /></button><div className="ml-1 flex items-center gap-2 border-l border-border pl-3"><div className="grid size-8 place-items-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">AM</div><div className="hidden text-left sm:block"><p className="text-xs font-medium">Alex Morgan</p><p className="text-[10px] text-muted-foreground">Engineering lead</p></div><ChevronDown className="hidden size-3.5 text-muted-foreground sm:block" /></div></div></header> }

export function AppShell({ children, path, onNavigate }: { children: React.ReactNode; path: string; onNavigate: (href: string) => void }) { const [menu, setMenu] = useState(false); const [command, setCommand] = useState(false); const [dark, setDark] = useState(false); const toggleTheme = () => { setDark(v => !v); document.documentElement.classList.toggle('dark', !dark) }; return <div className="min-h-screen bg-background text-foreground"><Sidebar path={path} onNavigate={href => { onNavigate(href); setMenu(false) }} open={menu} onClose={() => setMenu(false)} /><div className="md:pl-64"><Topbar onMenu={() => setMenu(true)} onCommand={() => setCommand(true)} onTheme={toggleTheme} /><main className="mx-auto max-w-[1500px] p-4 md:p-8">{children}</main></div>{command && <CommandPalette onClose={() => setCommand(false)} onNavigate={onNavigate} />}</div> }

function CommandPalette({ onClose, onNavigate }: { onClose: () => void; onNavigate: (href: string) => void }) { return <div className="fixed inset-0 z-[60] grid place-items-start justify-center bg-foreground/25 px-4 pt-[15vh] backdrop-blur-sm" onClick={onClose}><div className="w-full max-w-xl overflow-hidden rounded-xl border border-border bg-popover shadow-2xl" onClick={e => e.stopPropagation()}><div className="flex items-center gap-3 border-b border-border px-4"><Search className="size-4 text-muted-foreground" /><input autoFocus placeholder="Search repositories, pull requests, findings..." className="h-14 flex-1 bg-transparent text-sm outline-none" /><kbd className="rounded border border-border px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">ESC</kbd></div><div className="p-2"><p className="px-3 py-2 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Navigate</p>{nav.slice(0, 5).map(item => { const Icon = item.icon; return <button key={item.href} onClick={() => { onNavigate(item.href); onClose() }} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-sm hover:bg-muted"><Icon className="size-4 text-muted-foreground" />{item.label}<ChevronRight className="ml-auto size-4 text-muted-foreground" /></button> })}</div><div className="border-t border-border px-4 py-3 text-[11px] text-muted-foreground">Tip: use <span className="font-mono">⌘ K</span> anywhere to open search</div></div></div> }

function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div>{eyebrow && <p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">{eyebrow}</p>}<h1 className="text-balance text-2xl font-semibold tracking-tight md:text-3xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div> }

export function Dashboard({ onNavigate }: { onNavigate: (href: string) => void }) { return <div><PageHeader eyebrow="Monday, August 12, 2026" title="Good morning, Alex" description="Here&apos;s the current health of your engineering environment." action={<div className="flex items-center gap-2"><button className="rounded-lg border border-border px-3 py-2 text-xs font-medium hover:bg-muted">Last 30 days <ChevronDown className="ml-1 inline size-3.5" /></button><button onClick={() => onNavigate('/app/repositories')} className="rounded-lg bg-primary px-3 py-2 text-xs font-medium text-primary-foreground shadow-sm hover:bg-primary/90"><GitBranch className="mr-1.5 inline size-3.5" />Connect repository</button></div>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><MetricCard label="Repository health" value="86 / 100" trend="↑ 8.4%" detail="vs previous 30 days · Healthy" /><MetricCard label="PR risk" value="32 / 100" trend="↓ 12.1%" tone="healthy" detail="Average risk score · Low" /><MetricCard label="Security score" value="91 / 100" trend="↑ 4.2%" detail="3 open findings · Good" chart="bars" /><MetricCard label="Code quality" value="87 / 100" trend="↑ 5.8%" detail="Maintainability index · Good" /><MetricCard label="Test coverage" value="78.6%" trend="↑ 2.4%" tone="warning" detail="Changed code · Needs focus" chart="bars" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.65fr_1fr]"><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div><h2 className="text-sm font-semibold">Engineering health trend</h2><p className="mt-1 text-xs text-muted-foreground">Combined health score across your repositories</p></div><button className="rounded-md p-1.5 text-muted-foreground hover:bg-muted"><MoreHorizontal className="size-4" /></button></div><div className="mt-7 h-48"><svg className="h-full w-full" preserveAspectRatio="none" viewBox="0 0 720 190" role="img" aria-label="Engineering health trend from 68 to 86"><defs><linearGradient id="healthFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#6366f1" stopOpacity=".22" /><stop offset="1" stopColor="#6366f1" stopOpacity="0" /></linearGradient></defs>{[30, 70, 110, 150].map(y => <line key={y} x1="0" x2="720" y1={y} y2={y} stroke="currentColor" className="text-border/70" strokeDasharray="3 5" />)}<path d="M0 146 C32 137 52 143 78 132 S121 128 148 138 S191 112 220 121 S269 106 298 111 S340 91 370 100 S414 88 446 92 S492 73 522 78 S567 61 598 68 S648 51 720 37 L720 190 L0 190Z" fill="url(#healthFill)" /><path d="M0 146 C32 137 52 143 78 132 S121 128 148 138 S191 112 220 121 S269 106 298 111 S340 91 370 100 S414 88 446 92 S492 73 522 78 S567 61 598 68 S648 51 720 37" fill="none" stroke="#6366f1" strokeWidth="3" strokeLinecap="round" /></svg></div><div className="mt-3 flex justify-between text-[10px] text-muted-foreground"><span>Jul 14</span><span>Jul 21</span><span>Jul 28</span><span>Aug 4</span><span>Aug 12</span></div></section><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div><h2 className="text-sm font-semibold">Attention needed</h2><p className="mt-1 text-xs text-muted-foreground">Signals that need your team&apos;s review</p></div><Badge tone="warning">4 open</Badge></div><div className="mt-5 flex flex-col gap-1">{[{icon: ShieldCheck, title: 'Critical vulnerability in customer-portal', meta: 'CVE-2026-2847 · 18 min ago', tone: 'critical' as Tone}, {icon: GitPullRequest, title: 'PR #142 has elevated risk', meta: 'payment-service · 2 hours ago', tone: 'warning' as Tone}, {icon: FileCode2, title: 'Coverage dropped below target', meta: 'identity-platform · 76%', tone: 'warning' as Tone}, {icon: Package, title: '7 dependencies need updates', meta: 'Across 3 repositories', tone: 'neutral' as Tone}].map(item => { const Icon = item.icon; return <button key={item.title} onClick={() => onNavigate('/app/security')} className="flex items-start gap-3 rounded-lg p-3 text-left hover:bg-muted"><div className={cn('mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg', item.tone === 'critical' ? 'bg-red-100 text-red-600 dark:bg-red-950/40 dark:text-red-300' : item.tone === 'warning' ? 'bg-amber-100 text-amber-600 dark:bg-amber-950/40 dark:text-amber-300' : 'bg-muted text-muted-foreground')}><Icon className="size-4" /></div><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium">{item.title}</p><p className="mt-1 text-[11px] text-muted-foreground">{item.meta}</p></div><ChevronRight className="mt-2 size-3.5 shrink-0 text-muted-foreground" /></button> })}</div></section></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Recent pull requests</h2><p className="mt-1 text-xs text-muted-foreground">Risk-weighted activity across your team</p></div><button onClick={() => onNavigate('/app/pull-requests')} className="text-xs font-medium text-primary hover:underline">View all</button></div><div className="mt-4 flex flex-col">{pullRequests.slice(0, 3).map(pr => <button key={pr.id} onClick={() => onNavigate(`/app/pull-requests/${pr.id}`)} className="flex items-center gap-3 border-t border-border/70 py-3 text-left first:border-0"><div className="grid size-8 shrink-0 place-items-center rounded-full bg-muted font-mono text-[10px] font-semibold">{pr.author}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium">#{pr.id} {pr.title}</p><p className="mt-1 text-[11px] text-muted-foreground">{pr.repo} · {pr.age}</p></div><div className="text-right"><Score value={pr.risk} tone={pr.risk > 60 ? 'critical' : pr.risk > 40 ? 'warning' : 'healthy'} /><p className="mt-0.5 text-[10px] text-muted-foreground">risk</p></div></button>)}</div></section><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Pull request activity</h2><p className="mt-1 text-xs text-muted-foreground">Opened, merged, and closed over time</p></div><Badge tone="healthy">+18.2%</Badge></div><div className="mt-5"><MiniChart bars color="cyan" /></div><div className="mt-4 flex gap-5 text-[11px] text-muted-foreground"><span><i className="mr-1.5 inline-block size-2 rounded-full bg-primary" />Opened <b className="ml-1 text-foreground">48</b></span><span><i className="mr-1.5 inline-block size-2 rounded-full bg-cyan-500" />Merged <b className="ml-1 text-foreground">36</b></span><span><i className="mr-1.5 inline-block size-2 rounded-full bg-muted-foreground" />Closed <b className="ml-1 text-foreground">7</b></span></div></section></div></div> }

export function Repositories({ onNavigate }: { onNavigate: (href: string) => void }) { const [query, setQuery] = useState(''); const filtered = repositories.filter(repo => repo.name.includes(query.toLowerCase())); return <div><PageHeader eyebrow="Engineering surface" title="Repositories" description="Monitor health, risk, and analysis status across every connected codebase." action={<button className="rounded-lg bg-primary px-3 py-2 text-xs font-medium text-primary-foreground"><GitBranch className="mr-1.5 inline size-3.5" />Connect GitHub</button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search repositories" className="h-10 w-full rounded-lg border border-border bg-card pl-9 pr-3 text-sm outline-none ring-primary/20 placeholder:text-muted-foreground focus:ring-4" /></div><button className="rounded-lg border border-border bg-card px-3 text-xs font-medium hover:bg-muted">All languages <ChevronDown className="ml-2 inline size-3.5" /></button><button className="rounded-lg border border-border bg-card px-3 text-xs font-medium hover:bg-muted">Sort: Health <ChevronDown className="ml-2 inline size-3.5" /></button></div><div className="overflow-hidden rounded-xl border border-border/80 bg-card shadow-sm"><div className="hidden grid-cols-[2fr_1fr_0.8fr_0.8fr_0.8fr_0.8fr_1fr] gap-4 border-b border-border bg-muted/30 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground md:grid"><span>Repository</span><span>Health</span><span>Open PRs</span><span>Security</span><span>Coverage</span><span>Risk</span><span>Last analysis</span></div>{filtered.map(repo => <button key={repo.name} onClick={() => onNavigate(`/app/repositories/${repo.name}`)} className="grid w-full gap-3 border-b border-border/70 px-4 py-4 text-left transition-colors last:border-0 hover:bg-muted/30 md:grid-cols-[2fr_1fr_0.8fr_0.8fr_0.8fr_0.8fr_1fr] md:items-center md:gap-4 md:px-5"><div className="flex min-w-0 items-center gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><Code2 className="size-4" /></div><div className="min-w-0"><p className="truncate text-sm font-medium">{repo.name}</p><p className="truncate text-[11px] text-muted-foreground">{repo.owner} · {repo.language}</p></div></div><div className="flex items-center gap-2 text-xs md:block"><span className="text-muted-foreground md:hidden">Health</span><Score value={repo.health} tone={repo.tone} /></div><div className="text-xs"><span className="text-muted-foreground md:hidden">Open PRs </span>{repo.prs}</div><div className="text-xs"><span className="text-muted-foreground md:hidden">Security </span><Badge tone={repo.tone === 'critical' ? 'warning' : 'healthy'}>{repo.security}</Badge></div><div className="font-mono text-xs"><span className="font-sans text-muted-foreground md:hidden">Coverage </span>{repo.coverage}</div><div className="text-xs"><span className="text-muted-foreground md:hidden">Risk </span><Badge tone={repo.risk === 'High' ? 'critical' : repo.risk === 'Medium' ? 'warning' : 'healthy'}>{repo.risk}</Badge></div><div className="text-[11px] text-muted-foreground">{repo.updated}</div></button>)}{filtered.length === 0 && <div className="p-10 text-center"><Search className="mx-auto size-7 text-muted-foreground" /><p className="mt-3 text-sm font-medium">No repositories found</p><p className="mt-1 text-xs text-muted-foreground">Try a different search term.</p></div>}</div></div> }

export function PullRequests({ onNavigate }: { onNavigate: (href: string) => void }) { return <div><PageHeader eyebrow="Change intelligence" title="Pull requests" description="Prioritize reviews with explainable risk scores across every change." action={<button className="rounded-lg border border-border px-3 py-2 text-xs font-medium hover:bg-muted"><GitPullRequest className="mr-1.5 inline size-3.5" />Configure review policy</button>} /><div className="mb-5 flex flex-wrap gap-2"><div className="flex rounded-lg border border-border bg-card p-1">{['All', 'Open', 'Needs review', 'High risk'].map((filter, i) => <button key={filter} className={cn('rounded-md px-3 py-1.5 text-xs font-medium', i === 0 ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground')}>{filter}</button>)}</div><div className="relative ml-auto"><Search className="absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" /><input placeholder="Search pull requests" className="h-9 rounded-lg border border-border bg-card pl-8 pr-3 text-xs outline-none focus:ring-4 focus:ring-primary/10" /></div></div><div className="overflow-hidden rounded-xl border border-border/80 bg-card shadow-sm"><div className="hidden grid-cols-[2fr_1.2fr_0.7fr_0.7fr_0.7fr_1fr_0.9fr] gap-4 border-b border-border bg-muted/30 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground md:grid"><span>Pull request</span><span>Author</span><span>Risk</span><span>Files</span><span>Coverage</span><span>Status</span><span>Created</span></div>{pullRequests.map(pr => <button key={pr.id} onClick={() => onNavigate(`/app/pull-requests/${pr.id}`)} className="grid w-full gap-3 border-b border-border/70 px-4 py-4 text-left last:border-0 hover:bg-muted/30 md:grid-cols-[2fr_1.2fr_0.7fr_0.7fr_0.7fr_1fr_0.9fr] md:items-center md:gap-4 md:px-5"><div className="min-w-0"><p className="truncate text-sm font-medium">#{pr.id} {pr.title}</p><p className="mt-1 truncate text-[11px] text-muted-foreground">{pr.repo}</p></div><div className="flex items-center gap-2 text-xs"><div className="grid size-6 place-items-center rounded-full bg-muted font-mono text-[9px] font-semibold">{pr.author}</div>{pr.author === 'AM' ? 'Alex Morgan' : 'Team member'}</div><div><span className="mr-1.5 text-muted-foreground md:hidden">Risk</span><Score value={pr.risk} tone={pr.risk > 60 ? 'critical' : pr.risk > 40 ? 'warning' : 'healthy'} /></div><div className="text-xs"><span className="mr-1.5 text-muted-foreground md:hidden">Files</span>{pr.files}</div><div className="font-mono text-xs"><span className="font-sans mr-1.5 text-muted-foreground md:hidden">Coverage</span>{pr.coverage}</div><div><Badge tone={pr.status === 'Needs review' ? 'warning' : 'neutral'}>{pr.status}</Badge></div><div className="text-[11px] text-muted-foreground">{pr.age}</div></button>)}</div></div> }

export function PRDetail() { return <div><button className="mb-5 text-xs text-muted-foreground hover:text-foreground"><ChevronRight className="mr-1 inline size-3 rotate-180" />Back to pull requests</button><PageHeader eyebrow="Pull request #142 · payment-service" title="Improve payment authorization" description="Opened by Alex Morgan · 2 hours ago · 18 files changed" action={<div className="flex items-center gap-2"><Badge tone="critical">72 / 100 · High risk</Badge><button className="rounded-lg border border-border p-2 hover:bg-muted"><MoreHorizontal className="size-4" /></button></div>} /><div className="mb-5 flex gap-2 overflow-x-auto border-b border-border"><button className="border-b-2 border-primary px-3 py-3 text-xs font-medium text-primary">Summary</button>{['Risk analysis', 'Security', 'Code quality', 'Testing', 'Dependencies', 'AI review', 'Changed files', 'Timeline'].map(tab => <button key={tab} className="whitespace-nowrap px-3 py-3 text-xs text-muted-foreground hover:text-foreground">{tab}</button>)}</div><div className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Risk analysis</h2><p className="mt-1 text-xs text-muted-foreground">Why this change received its score</p></div><div className="font-mono text-3xl font-semibold text-red-600 dark:text-red-400">72</div></div><div className="mt-6 flex flex-col gap-4">{[['Security findings', '+22', 'Two findings affect authorization paths'], ['Code complexity', '+14', 'Complexity increased in 4 files'], ['Changed files', '+10', '18 files across 3 critical modules'], ['Low coverage', '+12', 'Changed-code coverage is 58%'], ['Dependency changes', '+8', '2 packages with breaking updates']].map(([label, value, detail], i) => <div key={label} className="flex items-center gap-3"><div className="grid size-8 place-items-center rounded-lg bg-muted font-mono text-[10px]">{i + 1}</div><div className="min-w-0 flex-1"><div className="flex justify-between gap-3 text-xs"><span className="font-medium">{label}</span><span className="font-mono text-red-600 dark:text-red-400">{value}</span></div><p className="mt-1 text-[11px] text-muted-foreground">{detail}</p><div className="mt-2 h-1 rounded-full bg-muted"><div className="h-full rounded-full bg-red-400" style={{ width: `${[88, 62, 48, 58, 37][i]}%` }} /></div></div></div>)}</div></section><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><div className="flex items-center gap-2"><Sparkles className="size-4 text-primary" /><h2 className="text-sm font-semibold">AI review</h2><Badge>Generated</Badge></div><p className="mt-2 text-xs leading-5 text-muted-foreground">Static analysis found 3 deterministic issues. Verion AI added context and prioritized the findings below.</p><div className="mt-5 flex flex-col gap-4">{[['Critical finding', 'Missing authorization check', 'payment/service.ts:84', 'The endpoint validates authentication but does not verify that the current user owns the requested resource.'], ['Recommendation', 'Add ownership validation', 'payment/service.ts:86', 'Validate resource ownership before processing the request and return a consistent 403 response.']].map(([type, title, file, text]) => <div key={title} className="rounded-lg border border-border bg-muted/20 p-3"><div className="flex items-center justify-between"><Badge tone={type === 'Critical finding' ? 'critical' : 'neutral'}>{type}</Badge><span className="text-[10px] text-muted-foreground">94% confidence</span></div><p className="mt-3 text-xs font-medium">{title}</p><p className="mt-1 font-mono text-[10px] text-primary">{file}</p><p className="mt-2 text-[11px] leading-5 text-muted-foreground">{text}</p><div className="mt-3 flex gap-2"><button className="rounded-md border border-border px-2 py-1 text-[10px] font-medium hover:bg-muted">Mark resolved</button><button className="rounded-md px-2 py-1 text-[10px] text-muted-foreground hover:bg-muted">Dismiss</button></div></div>)}</div></section></div><div className="mt-5 grid gap-5 lg:grid-cols-3"><MiniInfo title="Security" value="2 findings" detail="1 high · 1 medium" tone="critical" icon={ShieldCheck} /><MiniInfo title="Testing" value="58% coverage" detail="12% below repository target" tone="warning" icon={Zap} /><MiniInfo title="Changed files" value="18 files" detail="+42% vs team median" tone="neutral" icon={FileCode2} /></div></div> }
function MiniInfo({ title, value, detail, tone, icon: Icon }: { title: string; value: string; detail: string; tone: Tone; icon: React.ElementType }) { return <div className="rounded-xl border border-border/80 bg-card p-4 shadow-sm"><div className="flex items-center gap-2 text-xs font-medium"><Icon className={cn('size-4', tone === 'critical' ? 'text-red-500' : tone === 'warning' ? 'text-amber-500' : 'text-primary')} />{title}</div><p className="mt-4 font-mono text-xl font-semibold">{value}</p><p className="mt-1 text-[11px] text-muted-foreground">{detail}</p></div> }

export function DataPage({ kind }: { kind: 'quality' | 'security' | 'dependencies' | 'analytics' }) { const configs = { quality: { eyebrow: 'Maintainability signals', title: 'Code quality', description: 'Understand maintainability before complexity becomes a delivery problem.', metrics: [['Quality score', '87 / 100'], ['Maintainability', '82 / 100'], ['Complexity', '1.8 avg'], ['Duplication', '3.2%'], ['Technical debt', '14h']], columns: ['Severity', 'Rule', 'File', 'Line', 'Category', 'Status'], rows: [['Medium', 'complexity-threshold', 'payment/service.ts', '84', 'Complexity', 'Open'], ['Low', 'no-duplicate-branches', 'checkout/tax.py', '121', 'Duplication', 'Open'], ['Medium', 'missing-error-context', 'auth/session.go', '57', 'Maintainability', 'Resolved']] }, security: { eyebrow: 'Threat surface', title: 'Security center', description: 'Track vulnerabilities, secrets, and dependency risk across your engineering environment.', metrics: [['Security score', '91 / 100'], ['Critical', '0'], ['High', '1'], ['Medium', '2'], ['Secrets', '0']], columns: ['Severity', 'Finding', 'CWE', 'File', 'Line', 'Status'], rows: [['High', 'Missing authorization check', 'CWE-862', 'payment/service.ts', '84', 'Open'], ['Medium', 'Weak session cookie flags', 'CWE-614', 'auth/session.go', '32', 'Open'], ['Medium', 'Outdated crypto library', 'CWE-1104', 'go.mod', '18', 'Resolved']] }, dependencies: { eyebrow: 'Supply chain health', title: 'Dependencies', description: 'Keep packages current, secure, and aligned with the health of your codebase.', metrics: [['Dependency health', '84 / 100'], ['Total packages', '248'], ['Outdated', '17'], ['Vulnerable', '3'], ['Abandoned', '2']], columns: ['Package', 'Current', 'Latest', 'Status', 'Vulnerability', 'License'], rows: [['stripe', '14.2.0', '14.3.1', 'Outdated', 'None', 'MIT'], ['axios', '1.6.2', '1.8.4', 'Vulnerable', 'CVE-2026-1120', 'MIT'], ['zod', '3.24.1', '3.24.1', 'Healthy', 'None', 'MIT']] }, analytics: { eyebrow: 'Engineering intelligence', title: 'Analytics', description: 'Measure the systems and behaviors that shape delivery quality.', metrics: [['PR throughput', '48 / month'], ['Merge frequency', '1.6 / day'], ['Review time', '6.2h'], ['Average PR size', '14 files'], ['Average risk', '32 / 100']], columns: ['Metric', 'Current period', 'Previous period', 'Change', 'Definition'], rows: [['PR throughput', '48', '41', '+17%', 'Merged pull requests'], ['Review time', '6.2 hours', '8.1 hours', '-23%', 'Median time to first review'], ['Deployment-related risk', '8.4%', '10.2%', '-18%', 'Deploys with follow-up issue']] } }[kind]; return <div><PageHeader eyebrow={configs.eyebrow} title={configs.title} description={configs.description} action={<div className="flex items-center gap-2"><button className="rounded-lg border border-border px-3 py-2 text-xs font-medium hover:bg-muted">30 days <ChevronDown className="ml-1 inline size-3.5" /></button><button className="rounded-lg bg-primary px-3 py-2 text-xs font-medium text-primary-foreground">Export report</button></div>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{configs.metrics.map(([label, value], i) => <div key={label} className="rounded-xl border border-border/80 bg-card p-4 shadow-sm"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-2 font-mono text-2xl font-semibold">{value}</p><p className={cn('mt-2 text-[11px]', i === 2 && kind !== 'analytics' ? 'text-amber-600 dark:text-amber-400' : 'text-emerald-600 dark:text-emerald-400')}>{i === 2 ? 'Needs attention' : '↑ 4.8% vs prior period'}</p></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1.25fr_0.75fr]"><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><h2 className="text-sm font-semibold">{kind === 'analytics' ? 'Delivery performance trend' : `${configs.title} trend`}</h2><p className="mt-1 text-xs text-muted-foreground">Rolling 30-day view across connected repositories</p><div className="mt-6"><MiniChart color={kind === 'security' ? 'green' : kind === 'dependencies' ? 'cyan' : kind === 'quality' ? 'primary' : 'amber'} /></div></section><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><h2 className="text-sm font-semibold">{kind === 'security' ? 'Severity breakdown' : kind === 'quality' ? 'Finding categories' : kind === 'analytics' ? 'Team signals' : 'Package status'}</h2><div className="mt-5 flex items-end gap-3">{[42, 68, 28, 55, 36].map((h, i) => <div key={i} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-md bg-primary/20" style={{ height: `${h * 1.4}px` }} /><span className="text-[10px] text-muted-foreground">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri'][i]}</span></div>)}</div></section></div><section className="mt-5 overflow-hidden rounded-xl border border-border/80 bg-card shadow-sm"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="text-sm font-semibold">{kind === 'analytics' ? 'Defined metrics' : 'Latest findings'}</h2><p className="mt-1 text-xs text-muted-foreground">Every signal includes context and a recovery path.</p></div><button className="rounded-md border border-border p-2 hover:bg-muted"><MoreHorizontal className="size-4" /></button></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-xs"><thead className="bg-muted/30 text-[10px] uppercase tracking-wider text-muted-foreground"><tr>{configs.columns.map(column => <th key={column} className="px-5 py-3 font-semibold">{column}</th>)}</tr></thead><tbody>{configs.rows.map((row, ri) => <tr key={ri} className="border-t border-border/70"><>{row.map((cell, ci) => <td key={ci} className={cn('px-5 py-4', ci === 0 && kind !== 'analytics' && (cell === 'High' || cell === 'Medium') && 'font-medium text-amber-600 dark:text-amber-400', ci === row.length - 1 && cell === 'Open' && 'text-primary')}>{cell}</td>)}</></tr>)}</tbody></table></div></section></div> }

export function Settings({ onNavigate }: { onNavigate: (href: string) => void }) { const [saved, setSaved] = useState(false); return <div><PageHeader eyebrow="Workspace control" title="Settings" description="Manage your workspace, integrations, and notification preferences." /><div className="grid gap-6 lg:grid-cols-[220px_1fr]"><nav className="flex gap-1 overflow-auto lg:flex-col">{['Profile', 'Team', 'Integrations', 'Notifications', 'Security'].map((item, i) => <button key={item} onClick={() => i === 2 && onNavigate('/app/settings/integrations')} className={cn('whitespace-nowrap rounded-lg px-3 py-2 text-left text-xs font-medium', i === 0 ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}>{item}</button>)}</nav><section className="rounded-xl border border-border/80 bg-card p-5 shadow-sm"><h2 className="text-sm font-semibold">Profile</h2><p className="mt-1 text-xs text-muted-foreground">Your personal account details and preferences.</p><div className="mt-6 grid max-w-xl gap-5 sm:grid-cols-2"><label className="grid gap-2 text-xs font-medium">Full name<input defaultValue="Alex Morgan" className="h-10 rounded-lg border border-border bg-background px-3 text-sm font-normal outline-none focus:ring-4 focus:ring-primary/10" /></label><label className="grid gap-2 text-xs font-medium">Timezone<select defaultValue="Pacific Time" className="h-10 rounded-lg border border-border bg-background px-3 text-sm font-normal outline-none focus:ring-4 focus:ring-primary/10"><option>Pacific Time</option><option>Eastern Time</option><option>UTC</option></select></label><label className="grid gap-2 text-xs font-medium sm:col-span-2">Email address<input defaultValue="alex@acme.dev" className="h-10 rounded-lg border border-border bg-background px-3 text-sm font-normal outline-none focus:ring-4 focus:ring-primary/10" /></label></div><div className="mt-7 flex items-center gap-3 border-t border-border pt-5"><button onClick={() => setSaved(true)} className="rounded-lg bg-primary px-4 py-2 text-xs font-medium text-primary-foreground">Save changes</button>{saved && <span className="text-xs text-emerald-600 dark:text-emerald-400">Settings saved successfully.</span>}</div></section></div></div> }

export function Help() { return <div><PageHeader eyebrow="Resources" title="Help center" description="Learn how Verion turns code changes into engineering decisions." action={<div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input placeholder="Search help" className="h-10 rounded-lg border border-border bg-card pl-9 pr-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" /></div>} /><div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{[{icon: BookOpen, title: 'Getting started', text: 'Connect GitHub and run your first repository analysis.'}, {icon: GitBranch, title: 'GitHub integration', text: 'Understand permissions, webhooks, and repository sync.'}, {icon: ShieldCheck, title: 'Understanding risk scores', text: 'Learn how Verion weighs change complexity and findings.'}, {icon: Code2, title: 'Code quality', text: 'Explore maintainability, complexity, and technical debt.'}, {icon: Sparkles, title: 'AI reviews', text: 'See how AI context complements deterministic analysis.'}, {icon: HelpCircle, title: 'Frequently asked questions', text: 'Answers to the questions teams ask most often.'}].map(item => { const Icon = item.icon; return <button key={item.title} className="rounded-xl border border-border/80 bg-card p-5 text-left shadow-sm transition-colors hover:border-primary/40 hover:bg-primary/[.02]"><Icon className="size-5 text-primary" /><h2 className="mt-5 text-sm font-semibold">{item.title}</h2><p className="mt-2 text-xs leading-5 text-muted-foreground">{item.text}</p><span className="mt-5 inline-flex items-center text-xs font-medium text-primary">Read guide <ChevronRight className="ml-1 size-3.5" /></span></button>})}</div></div> }

export function Landing({ onNavigate }: { onNavigate: (href: string) => void }) { return <div className="min-h-screen bg-background text-foreground"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 md:px-8"><Logo /><nav className="hidden items-center gap-7 text-xs text-muted-foreground md:flex"><a href="#features" className="hover:text-foreground">Features</a><a href="#security" className="hover:text-foreground">Security</a><a href="#pricing" className="hover:text-foreground">Pricing</a><a href="#about" className="hover:text-foreground">About</a></nav><div className="flex items-center gap-2"><button onClick={() => onNavigate('/login')} className="hidden rounded-lg px-3 py-2 text-xs font-medium text-muted-foreground hover:text-foreground sm:block">Sign in</button><button onClick={() => onNavigate('/signup')} className="rounded-lg bg-primary px-3 py-2 text-xs font-medium text-primary-foreground shadow-sm">Start free</button></div></header><main><section className="mx-auto max-w-7xl px-5 pb-16 pt-14 md:px-8 md:pb-24 md:pt-24"><div className="max-w-3xl"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/20 bg-primary/5 px-3 py-1.5 text-[11px] font-medium text-primary"><span className="size-1.5 rounded-full bg-emerald-500" />Now analyzing 12,840 code changes</div><h1 className="text-balance text-5xl font-semibold tracking-[-0.04em] md:text-7xl">Engineering intelligence for <span className="text-primary">every code change.</span></h1><p className="mt-6 max-w-xl text-base leading-7 text-muted-foreground md:text-lg">Analyze pull requests, detect vulnerabilities, measure code health, and identify engineering risk before your code reaches production.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={() => onNavigate('/signup')} className="rounded-lg bg-primary px-5 py-3 text-sm font-medium text-primary-foreground shadow-lg shadow-primary/15">Start free <ChevronRight className="ml-1 inline size-4" /></button><button onClick={() => onNavigate('/app/dashboard')} className="rounded-lg border border-border bg-card px-5 py-3 text-sm font-medium hover:bg-muted"><LineChart className="mr-1.5 inline size-4" />View demo</button></div><div className="mt-7 flex flex-wrap gap-x-5 gap-y-2 text-[11px] text-muted-foreground"><span><ShieldCheck className="mr-1 inline size-3.5 text-emerald-500" />SOC 2-ready architecture</span><span><GitBranch className="mr-1 inline size-3.5" />Native GitHub workflow</span><span><Zap className="mr-1 inline size-3.5 text-amber-500" />Analysis in minutes</span></div></div><div className="relative mt-16 overflow-hidden rounded-2xl border border-border bg-card shadow-2xl shadow-primary/10"><div className="flex items-center gap-2 border-b border-border bg-muted/30 px-4 py-3"><div className="flex gap-1.5"><span className="size-2 rounded-full bg-red-400" /><span className="size-2 rounded-full bg-amber-400" /><span className="size-2 rounded-full bg-emerald-400" /></div><span className="ml-3 font-mono text-[10px] text-muted-foreground">app.verion.dev / dashboard</span></div><div className="grid min-h-[360px] grid-cols-[150px_1fr] md:grid-cols-[205px_1fr]"><div className="hidden border-r border-border bg-muted/10 p-4 sm:block"><Logo compact /><div className="mt-8 flex flex-col gap-2">{['Dashboard', 'Repositories', 'Pull Requests', 'Code Quality', 'Security', 'Dependencies'].map((x, i) => <div key={x} className={cn('rounded-md px-2 py-2 text-[10px]', i === 0 ? 'bg-primary text-primary-foreground' : 'text-muted-foreground')}>{x}</div>)}</div></div><div className="p-4 md:p-6"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-wider text-primary">Engineering surface</p><h3 className="mt-1 text-lg font-semibold">Good morning, Alex</h3></div><div className="hidden rounded-md border border-border px-2 py-1 text-[10px] text-muted-foreground sm:block">Last 30 days</div></div><div className="mt-5 grid grid-cols-2 gap-3 lg:grid-cols-4">{[['Repository health', '86 / 100'], ['PR risk', '32 / 100'], ['Security score', '91 / 100'], ['Test coverage', '78.6%']].map(([l, v]) => <div key={l} className="rounded-lg border border-border p-3"><p className="text-[9px] text-muted-foreground">{l}</p><p className="mt-2 font-mono text-sm font-semibold">{v}</p><div className="mt-3"><MiniChart color="primary" /></div></div>)}</div><div className="mt-3 grid gap-3 lg:grid-cols-[1.35fr_1fr]"><div className="rounded-lg border border-border p-3"><p className="text-[10px] font-medium">Engineering health trend</p><div className="mt-4"><MiniChart color="primary" /></div></div><div className="rounded-lg border border-border p-3"><p className="text-[10px] font-medium">Attention needed</p><div className="mt-4 flex flex-col gap-2">{['Critical vulnerability', 'PR #142 elevated risk', 'Coverage below target'].map((x, i) => <div key={x} className="flex items-center gap-2 rounded-md bg-muted/40 p-2 text-[10px]"><span className={cn('size-1.5 rounded-full', i === 0 ? 'bg-red-500' : 'bg-amber-500')} />{x}</div>)}</div></div></div></div></div></div></section><section id="features" className="border-y border-border bg-muted/20"><div className="mx-auto max-w-7xl px-5 py-16 md:px-8 md:py-20"><div className="max-w-xl"><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">One system of truth</p><h2 className="mt-3 text-3xl font-semibold tracking-tight md:text-4xl">Move from code volume to engineering clarity.</h2><p className="mt-4 text-sm leading-6 text-muted-foreground">Verion connects the signals your team already generates and turns them into a shared language for shipping safer software.</p></div><div className="mt-10 grid gap-4 md:grid-cols-3">{[{icon: GitPullRequest, title: 'Change intelligence', text: 'Prioritize pull requests with risk scores grounded in the files, coverage, and history of each change.'}, {icon: ShieldCheck, title: 'Security context', text: 'Surface real vulnerabilities with severity, CWE, affected lines, and remediation teams can act on.'}, {icon: BarChart3, title: 'Engineering health', text: 'Track quality, testing, dependencies, and delivery patterns without vanity metrics.'}].map(item => { const Icon = item.icon; return <div key={item.title} className="rounded-xl border border-border bg-card p-5 shadow-sm"><div className="grid size-9 place-items-center rounded-lg bg-primary/10 text-primary"><Icon className="size-4" /></div><h3 className="mt-6 text-sm font-semibold">{item.title}</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">{item.text}</p></div>})}</div></div></section><section id="security" className="mx-auto grid max-w-7xl gap-10 px-5 py-16 md:grid-cols-2 md:px-8 md:py-24"><div><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">Built for the merge queue</p><h2 className="mt-3 text-3xl font-semibold tracking-tight">Catch the signal before it becomes an incident.</h2><p className="mt-4 text-sm leading-6 text-muted-foreground">From a missing authorization check to a slow drift in coverage, Verion gives every change the context it deserves.</p><div className="mt-7 flex flex-col gap-4">{['Deterministic findings stay distinct from AI suggestions', 'Risk scores explain the factors behind the number', 'Every recommendation points to a practical next step'].map(x => <div key={x} className="flex items-center gap-3 text-sm"><div className="grid size-6 place-items-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/40 dark:text-emerald-300"><ShieldCheck className="size-3.5" /></div>{x}</div>)}</div></div><div className="rounded-2xl border border-border bg-card p-5 shadow-xl"><div className="flex items-center gap-2"><div className="grid size-7 place-items-center rounded-lg bg-primary text-xs font-bold text-primary-foreground">V</div><div><p className="text-xs font-semibold">AI review · PR #142</p><p className="text-[10px] text-muted-foreground">payment-service</p></div><Badge tone="critical">High risk</Badge></div><div className="mt-5 rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-900/60 dark:bg-red-950/30"><div className="flex items-center gap-2"><ShieldCheck className="size-4 text-red-600 dark:text-red-300" /><span className="text-xs font-semibold text-red-700 dark:text-red-300">Missing authorization check</span></div><p className="mt-3 font-mono text-[10px] text-red-700/70 dark:text-red-300/70">payment/service.ts:84</p><p className="mt-2 text-xs leading-5 text-red-800/80 dark:text-red-200/80">The endpoint validates authentication but does not verify resource ownership.</p></div><div className="mt-4 grid grid-cols-3 gap-2">{[['Confidence', '94%'], ['Files', '18'], ['Coverage', '58%']].map(([l, v]) => <div key={l} className="rounded-lg bg-muted/50 p-3"><p className="text-[10px] text-muted-foreground">{l}</p><p className="mt-1 font-mono text-sm font-semibold">{v}</p></div>)}</div></div></section><section id="pricing" className="border-t border-border bg-muted/20"><div className="mx-auto max-w-7xl px-5 py-16 md:px-8 md:py-20"><div className="text-center"><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">Simple, transparent pricing</p><h2 className="mt-3 text-3xl font-semibold tracking-tight">Start with the signals you need.</h2></div><div className="mx-auto mt-10 grid max-w-5xl gap-4 md:grid-cols-3">{[{name: 'Free', price: '$0', text: 'For individual developers', features: ['2 repositories', 'Basic risk analysis', '7-day history']}, {name: 'Team', price: '$19', text: 'For small engineering teams', features: ['Unlimited repositories', 'AI review context', '90-day history'], featured: true}, {name: 'Business', price: 'Let’s talk', text: 'For growing organizations', features: ['SSO and audit logs', 'Custom policies', 'Priority support']}].map(plan => <div key={plan.name} className={cn('rounded-xl border p-5 shadow-sm', plan.featured ? 'border-primary bg-card ring-1 ring-primary' : 'border-border bg-card')}><div className="flex items-center justify-between"><h3 className="text-sm font-semibold">{plan.name}</h3>{plan.featured && <Badge tone="healthy">Popular</Badge>}</div><p className="mt-5 font-mono text-3xl font-semibold">{plan.price}<span className="font-sans text-xs font-normal text-muted-foreground">{plan.price.startsWith('$') && plan.price !== '$0' ? ' / seat / month' : ''}</span></p><p className="mt-2 text-xs text-muted-foreground">{plan.text}</p><button onClick={() => onNavigate(plan.name === 'Business' ? '/about' : '/signup')} className={cn('mt-6 w-full rounded-lg px-3 py-2.5 text-xs font-medium', plan.featured ? 'bg-primary text-primary-foreground' : 'border border-border hover:bg-muted')}>{plan.name === 'Business' ? 'Contact sales' : 'Start free'}</button><div className="mt-6 flex flex-col gap-3">{plan.features.map(feature => <p key={feature} className="text-xs text-muted-foreground"><span className="mr-2 text-emerald-500">✓</span>{feature}</p>)}</div></div>)}</div></div></section></main><footer className="border-t border-border"><div className="mx-auto flex max-w-7xl flex-col gap-5 px-5 py-8 text-xs text-muted-foreground md:flex-row md:items-center md:justify-between md:px-8"><div><Logo /><p className="mt-3">Engineering Intelligence for Every Code Change.</p></div><div className="flex flex-wrap gap-x-5 gap-y-2"><a href="#features" className="hover:text-foreground">Features</a><a href="#security" className="hover:text-foreground">Security</a><a href="#pricing" className="hover:text-foreground">Pricing</a><a href="#about" className="hover:text-foreground">About</a><span>© 2026 Verion</span></div></div></footer></div> }

export function AuthPage({ mode, onNavigate }: { mode: 'login' | 'signup' | 'forgot' | 'reset'; onNavigate: (href: string) => void }) {
  const [show, setShow] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const title = mode === 'login' ? 'Welcome back' : mode === 'signup' ? 'Create your workspace' : mode === 'forgot' ? 'Reset your password' : 'Choose a new password'
  if (submitted) return <div className="grid min-h-screen place-items-center bg-muted/20 p-5"><div className="w-full max-w-md rounded-2xl border border-border bg-card p-8 text-center shadow-xl"><Logo /><div className="mx-auto mt-10 grid size-12 place-items-center rounded-full bg-emerald-100 text-emerald-600"><ShieldCheck className="size-5" /></div><h1 className="mt-5 text-xl font-semibold">Check your inbox</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">Your request was received. Continue when you are ready.</p><button onClick={() => onNavigate(mode === 'signup' ? '/onboarding' : '/app/dashboard')} className="mt-7 w-full rounded-lg bg-primary py-3 text-sm font-medium text-primary-foreground">Continue</button></div></div>
  return <div className="grid min-h-screen bg-muted/20 lg:grid-cols-2"><div className="hidden flex-col justify-between bg-primary p-10 text-primary-foreground lg:flex"><Logo /><div className="max-w-md"><Sparkles className="mb-5 size-7" /><h2 className="text-4xl font-semibold tracking-tight">Make every change safer to ship.</h2><p className="mt-5 text-sm leading-6 text-primary-foreground/70">Verion brings code quality, security, testing, and engineering risk into one clear workflow.</p></div><p className="text-xs text-primary-foreground/50">© 2026 Verion</p></div><div className="flex items-center justify-center p-5"><div className="w-full max-w-md"><div className="mb-8 lg:hidden"><Logo /></div><div className="rounded-2xl border border-border bg-card p-6 shadow-xl sm:p-8"><h1 className="text-2xl font-semibold tracking-tight">{title}</h1><p className="mt-2 text-sm text-muted-foreground">Sign in to your engineering workspace.</p><div className="mt-7 flex flex-col gap-4">{mode === 'signup' && <label className="grid gap-2 text-xs font-medium">Full name<input placeholder="Alex Morgan" className="h-10 rounded-lg border border-border bg-background px-3 text-sm font-normal" /></label>}<label className="grid gap-2 text-xs font-medium">Email address<input type="email" placeholder="you@company.com" className="h-10 rounded-lg border border-border bg-background px-3 text-sm font-normal" /></label>{mode !== 'forgot' && <label className="grid gap-2 text-xs font-medium">Password<div className="relative"><input type={show ? 'text' : 'password'} placeholder="At least 8 characters" className="h-10 w-full rounded-lg border border-border bg-background px-3 pr-10 text-sm font-normal" /><button type="button" onClick={() => setShow(!show)} className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-muted-foreground" aria-label="Toggle password visibility"><Sun className="size-4" /></button></div></label>}<button onClick={() => setSubmitted(true)} className="rounded-lg bg-primary py-3 text-sm font-medium text-primary-foreground">{mode === 'login' ? 'Sign in' : mode === 'forgot' ? 'Send reset link' : 'Create workspace'}</button>{mode === 'login' && <button className="rounded-lg border border-border py-3 text-sm font-medium hover:bg-muted"><GitBranch className="mr-2 inline size-4" />Continue with GitHub</button>}</div>{mode === 'login' && <div className="mt-5 flex justify-between text-xs"><button onClick={() => onNavigate('/forgot-password')} className="text-primary hover:underline">Forgot password?</button><button onClick={() => onNavigate('/signup')} className="text-muted-foreground hover:text-foreground">Create account</button></div>}{mode === 'signup' && <p className="mt-5 text-center text-xs text-muted-foreground">Already have an account? <button onClick={() => onNavigate('/login')} className="text-primary hover:underline">Sign in</button></p>}</div></div></div></div>
}

export function Onboarding({ onNavigate }: { onNavigate: (href: string) => void }) {
  const [step, setStep] = useState(1)
  return <div className="min-h-screen bg-muted/20 p-5"><div className="mx-auto max-w-2xl"><Logo /><div className="mt-12 rounded-2xl border border-border bg-card p-8 text-center shadow-xl"><div className="mx-auto grid size-14 place-items-center rounded-2xl bg-primary text-primary-foreground"><Sparkles className="size-6" /></div><p className="mt-6 text-xs font-semibold uppercase tracking-wider text-primary">Step {step} of 3</p><h1 className="mt-3 text-2xl font-semibold">{step === 1 ? 'Welcome to Verion' : step === 2 ? 'Connect GitHub' : 'You’re ready to ship safer'}</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-muted-foreground">{step === 1 ? 'Set up the signals your team needs to ship with confidence.' : step === 2 ? 'Connect your repositories to begin analysis.' : 'Your workspace is ready for its first analysis.'}</p><div className="mt-8 flex justify-center gap-3"><button onClick={() => step === 1 ? onNavigate('/app/dashboard') : setStep(step - 1)} className="rounded-lg border border-border px-4 py-2.5 text-xs font-medium">{step === 1 ? 'Skip setup' : 'Back'}</button><button onClick={() => step === 3 ? onNavigate('/app/dashboard') : setStep(step + 1)} className="rounded-lg bg-primary px-5 py-2.5 text-xs font-medium text-primary-foreground">{step === 3 ? 'Go to dashboard' : 'Continue'}</button></div></div></div></div>
}

export default function VerionApp() { const [path, setPath] = useState(typeof window !== 'undefined' ? window.location.pathname : '/'); const navigate = (href: string) => { window.history.pushState({}, '', href); setPath(href); window.scrollTo(0, 0) }; useEffect(() => { const listener = () => setPath(window.location.pathname); window.addEventListener('popstate', listener); return () => window.removeEventListener('popstate', listener) }, []); if (path === '/' || path === '/features' || path === '/pricing' || path === '/security' || path === '/about') return <Landing onNavigate={navigate} />; if (path === '/login' || path === '/signup' || path === '/forgot-password' || path === '/reset-password') return <AuthPage mode={path === '/login' ? 'login' : path === '/signup' ? 'signup' : path === '/forgot-password' ? 'forgot' : 'reset'} onNavigate={navigate} />; if (path === '/onboarding') return <Onboarding onNavigate={navigate} />; const content = path.includes('/pull-requests/') ? <PRDetail /> : path === '/app/repositories' ? <Repositories onNavigate={navigate} /> : path === '/app/pull-requests' ? <PullRequests onNavigate={navigate} /> : path === '/app/code-quality' ? <DataPage kind="quality" /> : path === '/app/security' ? <DataPage kind="security" /> : path === '/app/dependencies' ? <DataPage kind="dependencies" /> : path === '/app/analytics' ? <DataPage kind="analytics" /> : path.startsWith('/app/settings') ? <Settings onNavigate={navigate} /> : path === '/app/help' ? <Help /> : <Dashboard onNavigate={navigate} />; return <AppShell path={path} onNavigate={navigate}>{content}</AppShell> }
